DROP TABLE IF EXISTS `TblEmpresa`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TblEmpresa` (
  `id_empresa` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID ├║nico de la empresa',
  `ruc` varchar(11) DEFAULT NULL,
  `nombre` varchar(255) NOT NULL COMMENT 'Nombre de la empresa',
  `latitud` decimal(10,8) NOT NULL COMMENT 'Latitud de la ubicaci├│n GPS',
  `longitud` decimal(11,8) NOT NULL COMMENT 'Longitud de la ubicaci├│n GPS',
  `radio_metros` int(11) NOT NULL DEFAULT 100 COMMENT 'Radio en metros permitido para marcar',
  `activa` tinyint(1) DEFAULT 1 COMMENT 'Estado de la empresa (1: activa, 0: inactiva)',
  `fecha_creacion` timestamp NULL DEFAULT current_timestamp() COMMENT 'Fecha de creaci├│n del registro',
  `fecha_actualizacion` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'Fecha de ├║ltima actualizaci├│n',
  `logo` longblob DEFAULT NULL COMMENT 'Logo de la empresa en formato PNG',
  PRIMARY KEY (`id_empresa`),
  UNIQUE KEY `nombre` (`nombre`),
  UNIQUE KEY `ruc` (`ruc`),
  KEY `idx_nombre` (`nombre`),
  KEY `idx_activa` (`activa`),
  KEY `idx_ubicacion` (`latitud`,`longitud`),
  KEY `idx_ruc` (`ruc`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Almacena informaci├│n de empresas con datos de geolocalizaci├│n para control de marcaciones de asistencia';
