/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TblPresupuestoDetalle` (
  `id_detalle` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID ├║nico del item',
  `id_presupuesto` int(11) NOT NULL COMMENT 'Foreign Key: Presupuesto padre',
  `id_material` int(11) DEFAULT NULL,
  `tipo_item` enum('MATERIAL','SERVICIO') NOT NULL DEFAULT 'MATERIAL',
  `descripcion` varchar(500) DEFAULT NULL,
  `cantidad` decimal(10,2) NOT NULL DEFAULT 1.00 COMMENT 'Cantidad del material',
  `cantidad_original` decimal(10,2) DEFAULT NULL COMMENT 'Cantidad presupuestada originalmente',
  `cantidad_consumida` decimal(10,2) DEFAULT 0.00 COMMENT 'Cantidad usada en requerimientos',
  `cantidad_saldo` decimal(10,2) GENERATED ALWAYS AS (coalesce(`cantidad_original`,0) - coalesce(`cantidad_consumida`,0)) STORED COMMENT 'Saldo disponible = original - consumida',
  `precio_unitario` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'Precio unitario del material',
