DROP TABLE IF EXISTS `TblProyecto`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TblProyecto` (
  `id_proyecto` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID ├║nico del proyecto',
  `codigo_proyecto` varchar(50) NOT NULL COMMENT 'C├│digo ├║nico del proyecto (Ej: PRY-001)',
  `nombre` varchar(200) NOT NULL COMMENT 'Nombre del proyecto',
  `descripcion` longtext DEFAULT NULL COMMENT 'Descripci├│n detallada del proyecto',
  `fecha_creacion` datetime NOT NULL DEFAULT current_timestamp() COMMENT 'Fecha de creaci├│n',
  `fecha_actualizacion` datetime DEFAULT NULL ON UPDATE current_timestamp() COMMENT '├Ültima fecha de actualizaci├│n',
  PRIMARY KEY (`id_proyecto`),
  UNIQUE KEY `codigo_proyecto` (`codigo_proyecto`),
  KEY `idx_codigo_proyecto` (`codigo_proyecto`),
  KEY `idx_nombre` (`nombre`),
  KEY `idx_fecha_creacion` (`fecha_creacion`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tabla de proyectos';
/*!40101 SET character_set_client = @saved_cs_client */;

