--
-- Table structure for table `TblRegistroAprobacion`
--

DROP TABLE IF EXISTS `TblRegistroAprobacion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TblRegistroAprobacion` (
  `id_registro` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID ├║nico del registro',
  `id_tipo_documento` int(11) NOT NULL COMMENT '1=Presupuesto, 2=Requerimiento, 3=OT, etc',
  `id_documento_referencia` int(11) NOT NULL COMMENT 'id_presupuesto, id_requerimiento, etc',
  `numero_paso` int(11) NOT NULL COMMENT 'N├║mero del paso (1, 2, 3, etc)',
  `id_cargo_aprobador` int(11) DEFAULT NULL COMMENT 'Cargo que aprob├│ (FK TblCargo)',
  `num_documento_aprobador` int(11) DEFAULT NULL COMMENT 'Usuario que aprob├│ (FK TblPersona)',
  `estado_aprobacion` varchar(20) NOT NULL DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE, APROBADO, RECHAZADO',
  `comentario` longtext DEFAULT NULL COMMENT 'Comentarios del aprobador',
  `fecha_aprobacion` datetime DEFAULT NULL COMMENT 'Cu├índo fue aprobado/rechazado',
  `fecha_asignacion` datetime DEFAULT current_timestamp() COMMENT 'Cu├índo fue asignado el paso',
  PRIMARY KEY (`id_registro`),
  UNIQUE KEY `uk_paso_documento` (`id_tipo_documento`,`id_documento_referencia`,`numero_paso`),
  KEY `fk_registro_cargo` (`id_cargo_aprobador`),
  KEY `idx_documento` (`id_tipo_documento`,`id_documento_referencia`),
  KEY `idx_paso` (`numero_paso`,`estado_aprobacion`),
  KEY `idx_aprobador` (`num_documento_aprobador`),
  CONSTRAINT `fk_registro_aprobador` FOREIGN KEY (`num_documento_aprobador`) REFERENCES `TblPersona` (`num_documento`) ON DELETE SET NULL,
  CONSTRAINT `fk_registro_cargo` FOREIGN KEY (`id_cargo_aprobador`) REFERENCES `TblCargo` (`id_cargo`) ON DELETE SET NULL,
  CONSTRAINT `fk_registro_tipo_documento` FOREIGN KEY (`id_tipo_documento`) REFERENCES `TblTipoDocumentoAprobacion` (`id_tipo_documento`)
) ENGINE=InnoDB AUTO_INCREMENT=103 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Registro de aprobaciones/rechazos de cada paso del flujo';
/*!40101 SET character_set_client = @saved_cs_client */;

