CREATE DEFINER=`kallgwkn_user`@`localhost` PROCEDURE `sp_ObtenerProyectos`()
BEGIN
    SELECT 
        id_proyecto,
        nombre
    FROM TblProyecto
    ORDER BY nombre ASC;
END ;;
